-- Trenerki Academy — reproducible learning-content update.
BEGIN;
insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('introligator-tradycja',0,'1. Budowa książki: blok, składki, grzbiet, okładki i wyklejki','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Książka to układ współpracujących części","text":"Blok książki (text block) zawiera zszyte lub inaczej połączone karty. Składka (signature) to zespół złożonych arkuszy. Grzbiet stanowi krawędź łączenia; okładka twarda składa się z tektury i materiału pokryciowego. Wyklejki łączą lub wykańczają blok i oprawę, ale ich funkcja zależy od konstrukcji książki."},{"heading":"Rozpoznaj przegub i zewnętrzny staw","text":"Przegub (hinge) to elastyczna strefa wewnętrzna między okładką a blokiem, dzięki której książka może się otwierać. Zewnętrzny joint jest jego odpowiednikiem w oprawie. Kiedy brakuje odpowiedniego miejsca na ruch, otwieranie okładki obciąża wyklejki lub zewnętrzną okleinę."},{"heading":"Zrozum krawędzie i margines","text":"Krawędź przednia (fore-edge) jest przeciwna do grzbietu, head to góra bloku, tail to dół. Gutter to wewnętrzny margines widoczny po otwarciu książki. Przy projekcie trzeba przewidzieć, ile treści zostanie blisko grzbietu, aby druk nie znikał w zagłębieniu."},{"heading":"Sytuacja z naprawy","text":"Czytelnik mówi ''kartki odpadają'', ale po oględzinach okazuje się, że blok jest dobrze zszyty, a odpadła jedna okładka przy przegubie. To nie jest ta sama usterka co rozerwany grzbiet bloku: diagnoza musi wskazywać konkretną część."},{"heading":"Ćwiczenie podstawowe","text":"Narysuj książkę w trzech widokach: zamkniętą z boku, otwartą i przekrój grzbietu. Podpisz 10 terminów, a następnie zaznacz różnymi kolorami części podtrzymujące blok, łączące z okładką i umożliwiające ruch."}],"illustration":"introligator-anatomia","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://guides.library.utoronto.ca/c.php?g=747378&p=5418809"}],"learning":{"intro":"Blok książki (text block) zawiera zszyte lub inaczej połączone karty. Składka (signature) to zespół złożonych arkuszy. Grzbiet stanowi krawędź łączenia; okładka twarda składa się z tektury i materiału pokryciowego. Wyklejki łączą lub wykańczają blok i oprawę, ale ich funkcja zależy od konstrukcji książki.","situation":"Czytelnik mówi ''kartki odpadają'', ale po oględzinach okazuje się, że blok jest dobrze zszyty, a odpadła jedna okładka przy przegubie. To nie jest ta sama usterka co rozerwany grzbiet bloku: diagnoza musi wskazywać konkretną część.","question":"Okładka odchyla się, lecz blok pozostaje zszyty. Która strefa konstrukcji prawdopodobnie wymaga oględzin?","options":["Głównie barwa papieru na przedniej krawędzi.","Wyłącznie numeracja ostatniej strony.","Przegub między blokiem a okładką i jego elementy łączące.","Wyłącznie wysokość liter na tytułowej stronie."],"correct":2,"example":"Przegub między blokiem a okładką i jego elementy łączące.","explanation":"Przegub odpowiada za ruch i połączenie okładki z blokiem; sama integralność szycia nie gwarantuje stanu przegubu.","feedback":["Nie. Przegub odpowiada za ruch i połączenie okładki z blokiem; sama integralność szycia nie gwarantuje stanu przegubu.","Nie. Przegub odpowiada za ruch i połączenie okładki z blokiem; sama integralność szycia nie gwarantuje stanu przegubu.","Tak. Przegub odpowiada za ruch i połączenie okładki z blokiem; sama integralność szycia nie gwarantuje stanu przegubu.","Nie. Przegub odpowiada za ruch i połączenie okładki z blokiem; sama integralność szycia nie gwarantuje stanu przegubu."],"task":"Narysuj książkę w trzech widokach: zamkniętą z boku, otwartą i przekrój grzbietu. Podpisz 10 terminów, a następnie zaznacz różnymi kolorami części podtrzymujące blok, łączące z okładką i umożliwiające ruch."}}'::jsonb),
('introligator-tradycja',1,'2. Materiałoznawstwo: kierunek włókien, papier, tektura i płótno','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Kierunek włókien naprawdę ma znaczenie","text":"W papierze i tekturze włókna mają dominujący kierunek, który wpływa na zachowanie przy zginaniu oraz zmianach wilgotności. W oprawie zwykle dąży się do ułożenia kierunku włókien równolegle do grzbietu. Przy nietrafionym układzie karty mogą trudniej się otwierać, a okładka wykazywać wypaczenie."},{"heading":"Tektura, papier i płótno pracują inaczej","text":"Tektura introligatorska nadaje sztywność, papier wyklejkowy jest elastyczną częścią bloku, a płótno pokryciowe współpracuje z podłożem przez warstwę kleju. Grubość i sztywność dobiera się do formatu i ciężaru książki; nadmiernie sztywna okładka może nie współpracować z delikatnym blokiem."},{"heading":"Jak rozpoznać kierunek w prostym teście","text":"Do bezpiecznej próbki papieru wykonaj delikatne zgięcie w obu kierunkach bez tworzenia trwałego zagięcia. Kierunek łatwiejszego uginania może wskazać przebieg włókien, ale dla krytycznych prac dane dostawcy i wiarygodna metoda testu są ważniejsze niż zgadywanie."},{"heading":"Przykład źle dobranej tektury","text":"Dwie okładki mają 220 × 160 mm, ale w jednej kierunek włókien biegnie poprzecznie do grzbietu. Pod wpływem zmian wilgotności może wykazywać inne odkształcenie i stawiać opór przy otwieraniu. Oznaczenie kierunku w magazynie zmniejsza liczbę takich pomyłek."},{"heading":"Ćwiczenie materiałowe","text":"Porównaj trzy próbki: papier o znanym kierunku włókien, tekturę introligatorską i płótno. Zaznacz strzałką kierunek w każdym materiale, zapisz jego funkcję w książce i zaproponuj kryterium odrzucenia, np. deformację lub niewłaściwą sztywność."}],"illustration":"introligator-wlokna","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://guides.library.utoronto.ca/c.php?g=747378&p=5418809"}],"learning":{"intro":"W papierze i tekturze włókna mają dominujący kierunek, który wpływa na zachowanie przy zginaniu oraz zmianach wilgotności. W oprawie zwykle dąży się do ułożenia kierunku włókien równolegle do grzbietu. Przy nietrafionym układzie karty mogą trudniej się otwierać, a okładka wykazywać wypaczenie.","situation":"Dwie okładki mają 220 × 160 mm, ale w jednej kierunek włókien biegnie poprzecznie do grzbietu. Pod wpływem zmian wilgotności może wykazywać inne odkształcenie i stawiać opór przy otwieraniu. Oznaczenie kierunku w magazynie zmniejsza liczbę takich pomyłek.","question":"Jak zwykle orientuje się kierunek włókien papieru i tektury w oprawie książkowej?","options":["Równolegle do grzbietu, by materiał odpowiednio pracował przy otwieraniu.","Poprzecznie do grzbietu, bo zawsze daje mniejszą deformację.","Losowo, bo kierunek włókien nie wpływa na sztywność i zachowanie.","Wyłącznie według koloru zewnętrznej okleiny."],"correct":0,"example":"Równolegle do grzbietu, by materiał odpowiednio pracował przy otwieraniu.","explanation":"W większości prac introligatorskich orientacja równoległa do grzbietu ogranicza problemy z otwieraniem i odkształcaniem bloku.","feedback":["Tak. W większości prac introligatorskich orientacja równoległa do grzbietu ogranicza problemy z otwieraniem i odkształcaniem bloku.","Nie. W większości prac introligatorskich orientacja równoległa do grzbietu ogranicza problemy z otwieraniem i odkształcaniem bloku.","Nie. W większości prac introligatorskich orientacja równoległa do grzbietu ogranicza problemy z otwieraniem i odkształcaniem bloku.","Nie. W większości prac introligatorskich orientacja równoległa do grzbietu ogranicza problemy z otwieraniem i odkształcaniem bloku."],"task":"Porównaj trzy próbki: papier o znanym kierunku włókien, tekturę introligatorską i płótno. Zaznacz strzałką kierunek w każdym materiale, zapisz jego funkcję w książce i zaproponuj kryterium odrzucenia, np. deformację lub niewłaściwą sztywność."}}'::jsonb),
('introligator-tradycja',2,'3. Narzędzia introligatora: kostka, szydło, igła, prasa','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Narzędzia to etapy procesu","text":"Kostka introligatorska (bone folder) służy do dokładnego zaginania i wygładzania. Szydło umożliwia przygotowanie otworów pod szycie składek, igła i nić wykonują połączenie, prasa stabilizuje elementy podczas właściwych operacji. Nóż lub gilotyna służy do cięcia, ale stanowi osobną kategorię ryzyka."},{"heading":"Nie myl docisku z cięciem","text":"Prasa może utrzymywać równą geometrię lub pomagać w odpowiednio zaplanowanym procesie klejenia. Nie zastępuje noża do obrównania bloku. Zbyt silny docisk na niewłaściwych podkładkach może pozostawić ślad na powierzchni okładki i uszkodzić delikatny papier."},{"heading":"Kleje i pędzle","text":"Pędzel służy do równomiernego rozprowadzania dobranego kleju na określonej powierzchni. Wybór kleju zależy od materiałów, elastyczności i przeznaczenia. Kleje stosowane do tanich notesów nie są automatycznie odpowiednie do konserwacji historycznego obiektu."},{"heading":"Bezpieczeństwo ręcznej pracy","text":"Narzędzia z ostrzami i szydła przechowuj tak, aby ostrze nie było skierowane do dłoni. Papier powinien mieć stabilne podparcie, a cięcie z odpowiednią prowadnicą. Duże gilotyny i prasy mechaniczne obsługują jedynie osoby przygotowane, zgodnie z procedurą pracowni."},{"heading":"Ćwiczenie z etapami","text":"Przygotuj kartę siedmiu narzędzi: nazwa, operacja, rezultat, punkt kontroli, sposób przechowywania. Na osobnym rysunku opisz kolejność formowania zagięcia, przygotowania otworów i zszycia prostej składki z papieru ćwiczeniowego."}],"illustration":"technique-introligator-tradycja","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://chinapreservationtutorial.library.cornell.edu/content/basic-remedial-treatment/"}],"learning":{"intro":"Kostka introligatorska (bone folder) służy do dokładnego zaginania i wygładzania. Szydło umożliwia przygotowanie otworów pod szycie składek, igła i nić wykonują połączenie, prasa stabilizuje elementy podczas właściwych operacji. Nóż lub gilotyna służy do cięcia, ale stanowi osobną kategorię ryzyka.","situation":"Narzędzia z ostrzami i szydła przechowuj tak, aby ostrze nie było skierowane do dłoni. Papier powinien mieć stabilne podparcie, a cięcie z odpowiednią prowadnicą. Duże gilotyny i prasy mechaniczne obsługują jedynie osoby przygotowane, zgodnie z procedurą pracowni.","question":"Które narzędzie jest przeznaczone do wykonywania wyraźnych, kontrolowanych zagięć papieru?","options":["Prasa do okładek.","Kostka introligatorska.","Igła do szycia składek.","Szydło do otworów."],"correct":1,"example":"Kostka introligatorska.","explanation":"Kostka introligatorska pomaga kontrolować linię i gładkość zgięcia; pozostałe narzędzia służą innym operacjom.","feedback":["Nie. Kostka introligatorska pomaga kontrolować linię i gładkość zgięcia; pozostałe narzędzia służą innym operacjom.","Tak. Kostka introligatorska pomaga kontrolować linię i gładkość zgięcia; pozostałe narzędzia służą innym operacjom.","Nie. Kostka introligatorska pomaga kontrolować linię i gładkość zgięcia; pozostałe narzędzia służą innym operacjom.","Nie. Kostka introligatorska pomaga kontrolować linię i gładkość zgięcia; pozostałe narzędzia służą innym operacjom."],"task":"Przygotuj kartę siedmiu narzędzi: nazwa, operacja, rezultat, punkt kontroli, sposób przechowywania. Na osobnym rysunku opisz kolejność formowania zagięcia, przygotowania otworów i zszycia prostej składki z papieru ćwiczeniowego."}}'::jsonb),
('introligator-tradycja',3,'4. Folio i składka: oblicz liczbę arkuszy i stron','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Strona to nie karta","text":"Jedna karta ma dwie strony (recto i verso). Jeden arkusz złożony raz tworzy dwie karty, czyli cztery strony. Gdy kilka takich arkuszy włożymy jeden w drugi, powstanie składka. W zależności od formatu i konstrukcji trzeba kontrolować kolejność stron przed szyciem."},{"heading":"Obliczenie na konkretnej książce","text":"Załóż 64 strony wyraźnie ponumerowane. Jeden arkusz po jednokrotnym złożeniu daje cztery strony, więc potrzeba 64/4 = 16 arkuszy. Jeżeli w każdej składce znajdują się cztery arkusze, otrzymasz cztery składki po 16 stron. To przykład dla określonego sposobu składania, nie uniwersalna reguła dla każdego procesu drukarskiego."},{"heading":"Dlaczego układ stron przed złożeniem jest inny","text":"W druku do składania numery stron muszą być rozmieszczone tak, aby po złożeniu i zszyciu tworzyły prawidłową kolejność. Nie należy drukować po prostu stron 1–64 kolejno na jednej stronie dużego arkusza. To zagadnienie impozycji (imposition), czyli rozplanowania stron na arkuszu."},{"heading":"Przykład pomyłki","text":"Uczeń liczy 64 strony jako 64 arkusze i kupuje cztery razy za dużo papieru. Innym błędem jest ułożenie pojedynczych arkuszy tak, że po zszyciu strony 8 i 9 znajdują się w złej kolejności. Właśnie dlatego przed produkcją wykonuje się dummy, czyli makietę złożoną z pustych kartek."},{"heading":"Ćwiczenie na papierze","text":"Przygotuj makietę jednej składki z czterech arkuszy A4 złożonych na pół. Ponumeruj po złożeniu 16 stron, następnie rozłóż i zaznacz, gdzie numery znajdują się na arkuszach. Powtórz obliczenie dla książki 96-stronicowej (24 arkusze po cztery strony)."}],"illustration":"introligator-skladka","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://www.ibookbinding.com/wp-content/uploads/2014/10/July-2014-Inroductory-Lesson.pdf"}],"learning":{"intro":"Jedna karta ma dwie strony (recto i verso). Jeden arkusz złożony raz tworzy dwie karty, czyli cztery strony. Gdy kilka takich arkuszy włożymy jeden w drugi, powstanie składka. W zależności od formatu i konstrukcji trzeba kontrolować kolejność stron przed szyciem.","situation":"Uczeń liczy 64 strony jako 64 arkusze i kupuje cztery razy za dużo papieru. Innym błędem jest ułożenie pojedynczych arkuszy tak, że po zszyciu strony 8 i 9 znajdują się w złej kolejności. Właśnie dlatego przed produkcją wykonuje się dummy, czyli makietę złożoną z pustych kartek.","question":"Książka ma 64 strony, a jeden arkusz złożony raz daje cztery strony. Ile arkuszy potrzeba w tym uproszczonym projekcie?","options":["8 arkuszy.","32 arkusze.","64 arkusze.","16 arkuszy."],"correct":3,"example":"16 arkuszy.","explanation":"64/4=16 arkuszy; po jednym złożeniu każdy tworzy dwie karty, czyli cztery strony.","feedback":["Nie. 64/4=16 arkuszy; po jednym złożeniu każdy tworzy dwie karty, czyli cztery strony.","Nie. 64/4=16 arkuszy; po jednym złożeniu każdy tworzy dwie karty, czyli cztery strony.","Nie. 64/4=16 arkuszy; po jednym złożeniu każdy tworzy dwie karty, czyli cztery strony.","Tak. 64/4=16 arkuszy; po jednym złożeniu każdy tworzy dwie karty, czyli cztery strony."],"task":"Przygotuj makietę jednej składki z czterech arkuszy A4 złożonych na pół. Ponumeruj po złożeniu 16 stron, następnie rozłóż i zaznacz, gdzie numery znajdują się na arkuszach. Powtórz obliczenie dla książki 96-stronicowej (24 arkusze po cztery strony)."}}'::jsonb),
('introligator-tradycja',4,'5. Szycie składek: grzbiet i punkty połączenia','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Blok musi być otwieralny i trwały","text":"Szycie łączy składki w jeden blok. Punkty szycia (sewing stations) rozmieszcza się z uwzględnieniem wysokości bloku i rodzaju oprawy. Materiał nici oraz sposób przechodzenia między składkami wpływają na trwałość i możliwość otwierania; to nie jest zwykłe przypadkowe przewlekanie kilku kartek."},{"heading":"Od kolejności do geometrii","text":"Przed szyciem kontroluj liczbę składek, ich kolejność, kierunek włókien i prawidłową pozycję każdego zagięcia. Zbyt bliskie krawędzi dziurki mogą osłabić papier. Rozmieszczenie otworów musi być przewidziane w projekcie, a nie nanoszone na każdej składce zupełnie inaczej."},{"heading":"Nie wszystkie książki są szyte","text":"Oprawy klejone łączą luźne kartki inaczej niż oprawy szyte. Nie należy twierdzić, że jedna technika jest zawsze najlepsza niezależnie od nakładu, formatu i sposobu użytkowania. Dla książki, która ma być często otwierana płasko, konstrukcja musi to umożliwiać."},{"heading":"Przykład błędu","text":"W notesie z czterema składkami otwory w jednej wykonano przesunięte względem pozostałych. Po zszyciu grzbiet jest skręcony. Właściwa kontrola polega na porównaniu osi i punktów szycia przed rozpoczęciem łączenia."},{"heading":"Ćwiczenie z makietą","text":"Na schemacie czterech składek zaznacz miejsce grzbietu, trzy punkty szycia i kierunek przebiegu nici. Porównaj ten projekt z blokiem klejonym z pojedynczych kartek. Wskaż po dwa zalety, ograniczenia i sytuacje typowego zastosowania obu konstrukcji."}],"illustration":"technique-introligator-tradycja","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://guides.library.utoronto.ca/c.php?g=747378&p=5418809"}],"learning":{"intro":"Szycie łączy składki w jeden blok. Punkty szycia (sewing stations) rozmieszcza się z uwzględnieniem wysokości bloku i rodzaju oprawy. Materiał nici oraz sposób przechodzenia między składkami wpływają na trwałość i możliwość otwierania; to nie jest zwykłe przypadkowe przewlekanie kilku kartek.","situation":"W notesie z czterema składkami otwory w jednej wykonano przesunięte względem pozostałych. Po zszyciu grzbiet jest skręcony. Właściwa kontrola polega na porównaniu osi i punktów szycia przed rozpoczęciem łączenia.","question":"Dlaczego punkty szycia składek należy wyznaczać ze wspólnego szablonu?","options":["Aby poprawić kolor tuszu na stronach.","Aby uzyskać zgodne położenie otworów i prawidłowe ułożenie grzbietu.","Aby wyeliminować konieczność kontroli kolejności stron.","Aby zamienić szycie w technikę klejenia."],"correct":1,"example":"Aby uzyskać zgodne położenie otworów i prawidłowe ułożenie grzbietu.","explanation":"Powtarzalne pozycje otworów pozwalają prawidłowo złożyć i zszyć blok bez jego skręcania.","feedback":["Nie. Powtarzalne pozycje otworów pozwalają prawidłowo złożyć i zszyć blok bez jego skręcania.","Tak. Powtarzalne pozycje otworów pozwalają prawidłowo złożyć i zszyć blok bez jego skręcania.","Nie. Powtarzalne pozycje otworów pozwalają prawidłowo złożyć i zszyć blok bez jego skręcania.","Nie. Powtarzalne pozycje otworów pozwalają prawidłowo złożyć i zszyć blok bez jego skręcania."],"task":"Na schemacie czterech składek zaznacz miejsce grzbietu, trzy punkty szycia i kierunek przebiegu nici. Porównaj ten projekt z blokiem klejonym z pojedynczych kartek. Wskaż po dwa zalety, ograniczenia i sytuacje typowego zastosowania obu konstrukcji."}}'::jsonb),
('introligator-tradycja',5,'6. Oprawa twarda: tektura, grzbietówka, wyklejka i okleina','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Case binding to konstrukcja osobnej okładki","text":"W typowej oprawie twardej okładka (case) powstaje osobno z tekturowych okładzin, grzbietówki i materiału pokryciowego. Następnie łączy się ją z przygotowanym blokiem, często za pomocą wyklejek. To inne rozwiązanie niż przyklejenie jednej sztywnej tektury bezpośrednio na grzbiet."},{"heading":"Przegub musi mieć przestrzeń do ruchu","text":"Tekturowe okładziny nie powinny blokować otwierania książki. Między okładziną a strefą grzbietu przewiduje się miejsce na pracę przegubu, zależne od grubości tektury i projektu. Ustawienie pokrycia i kierunku włókien ma znaczenie dla zachowania kształtu."},{"heading":"Rozpoznaj rolę wyklejki","text":"Wyklejka może pomagać przy połączeniu bloku z okładką i estetycznie wykańczać wnętrze oprawy. Nie jest tym samym co karta tytułowa. Niewłaściwy klej, nadmierna ilość wilgoci albo złe ułożenie wyklejki mogą spowodować odkształcenia, fałdy lub wyrywanie papieru przy otwieraniu."},{"heading":"Przykład z wadą","text":"Wykonana okładka ma prawidłowy format, ale okładziny umieszczono zbyt blisko grzbietu. Po sklejeniu książka otwiera się z oporem, a wyklejka jest ciągnięta. Wymiar zewnętrzny nie wystarcza — trzeba sprawdzić ruch przegubu."},{"heading":"Ćwiczenie rysunkowe","text":"Narysuj osobno blok i rozłożoną twardą oprawę. Zaznacz dwie okładziny, grzbietówkę, przerwy przegubowe, materiał pokryciowy i wyklejkę. Przygotuj protokół odbioru: geometria, czytelność, ruch, stan klejenia i krawędzie."}],"illustration":"introligator-przegub","references":[{"label":"Materiały do dalszego sprawdzenia","url":"https://guides.library.utoronto.ca/c.php?g=747378&p=5418809"}],"learning":{"intro":"W typowej oprawie twardej okładka (case) powstaje osobno z tekturowych okładzin, grzbietówki i materiału pokryciowego. Następnie łączy się ją z przygotowanym blokiem, często za pomocą wyklejek. To inne rozwiązanie niż przyklejenie jednej sztywnej tektury bezpośrednio na grzbiet.","situation":"Wykonana okładka ma prawidłowy format, ale okładziny umieszczono zbyt blisko grzbietu. Po sklejeniu książka otwiera się z oporem, a wyklejka jest ciągnięta. Wymiar zewnętrzny nie wystarcza — trzeba sprawdzić ruch przegubu.","question":"Oprawa wygląda równo, ale książkę trudno otworzyć, a wyklejka się napina. Co jest prawdopodobną przyczyną?","options":["Zbyt szeroka strefa przegubu w każdej możliwej książce.","Niedopasowanie konstrukcji przegubu lub odległości okładzin od grzbietu.","Zawsze zbyt mała liczba stron w bloku.","Wyłącznie błędny kolor okleiny."],"correct":1,"example":"Niedopasowanie konstrukcji przegubu lub odległości okładzin od grzbietu.","explanation":"Połączenie bloku z okładką musi zostawić możliwość ruchu; prawidłowy wymiar zewnętrzny nie gwarantuje prawidłowego przegubu.","feedback":["Nie. Połączenie bloku z okładką musi zostawić możliwość ruchu; prawidłowy wymiar zewnętrzny nie gwarantuje prawidłowego przegubu.","Tak. Połączenie bloku z okładką musi zostawić możliwość ruchu; prawidłowy wymiar zewnętrzny nie gwarantuje prawidłowego przegubu.","Nie. Połączenie bloku z okładką musi zostawić możliwość ruchu; prawidłowy wymiar zewnętrzny nie gwarantuje prawidłowego przegubu.","Nie. Połączenie bloku z okładką musi zostawić możliwość ruchu; prawidłowy wymiar zewnętrzny nie gwarantuje prawidłowego przegubu."],"task":"Narysuj osobno blok i rozłożoną twardą oprawę. Zaznacz dwie okładziny, grzbietówkę, przerwy przegubowe, materiał pokryciowy i wyklejkę. Przygotuj protokół odbioru: geometria, czytelność, ruch, stan klejenia i krawędzie."}}'::jsonb),
('introligator-tradycja',6,'7. Błędy oprawy: pęknięty grzbiet, słabe zawiasy i odklejone kartki','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Objaw to nie diagnoza","text":"Książka może mieć odklejoną okładkę, naderwane wyklejki, pęknięty grzbiet, odłączone składki albo pojedynczą wypadniętą kartę. Te usterki mają inne mechanizmy, więc nie należy pokrywać każdego uszkodzenia tą samą warstwą kleju. Rozpoznanie zaczyna się od elementu, który przestał spełniać funkcję."},{"heading":"Ślad przy przegubie","text":"Jeżeli pęka miejsce między okładką a grzbietem, rozważ nieprawidłową konstrukcję przegubu, niezgodność materiałów, pracę wyklejki i obciążenia podczas otwierania. W książce często czytanej istotna jest trwałość wielokrotnego zginania, a nie tylko wytrzymałość w jednym zamknięciu."},{"heading":"Ślad w bloku","text":"Jeśli odrywają się karty, skontroluj czy blok jest szyty ze składek, czy klejony z luźnych kart. Wysunięta składka może wymagać innego sposobu naprawy niż kruszący się klej grzbietu. Nie wolno na siłę wciskać karty w grzbiet bez rozpoznania sposobu oryginalnego łączenia."},{"heading":"Przykład dwóch książek","text":"Notes A ma całkowicie odłączoną sztywną okładkę, ale strony trzymają się bloku. Notes B ma nienaruszoną okładkę, lecz rozsypujący się blok klejony. Przeprowadzenie identycznej naprawy dla obu może pozostawić rzeczywistą usterkę nierozwiązaną."},{"heading":"Ćwiczenie diagnostyczne","text":"Zrób tabelę dla pięciu objawów: miejscowy rozpad grzbietu, odklejona okładka, luźna karta, skręcony blok, fałda wyklejki. Dla każdego określ część, możliwą przyczynę, wymagany dowód i właściwy poziom interwencji."}],"illustration":"introligator-przegub","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://chinapreservationtutorial.library.cornell.edu/content/basic-remedial-treatment/"}],"learning":{"intro":"Książka może mieć odklejoną okładkę, naderwane wyklejki, pęknięty grzbiet, odłączone składki albo pojedynczą wypadniętą kartę. Te usterki mają inne mechanizmy, więc nie należy pokrywać każdego uszkodzenia tą samą warstwą kleju. Rozpoznanie zaczyna się od elementu, który przestał spełniać funkcję.","situation":"Notes A ma całkowicie odłączoną sztywną okładkę, ale strony trzymają się bloku. Notes B ma nienaruszoną okładkę, lecz rozsypujący się blok klejony. Przeprowadzenie identycznej naprawy dla obu może pozostawić rzeczywistą usterkę nierozwiązaną.","question":"Blok jest stabilnie zszyty, ale oderwała się twarda okładka. Co należy w pierwszej kolejności zdiagnozować?","options":["Wyłącznie liczbę arkuszy papieru użytych do druku.","Przegub, wyklejki i połączenie oprawy z blokiem.","Wyłącznie rozdzielczość obrazu na okładce.","Kolejność składania stron w każdej sygnaturze."],"correct":1,"example":"Przegub, wyklejki i połączenie oprawy z blokiem.","explanation":"Usterka dotyczy połączenia oprawy z blokiem, a niekoniecznie samego szycia składek.","feedback":["Nie. Usterka dotyczy połączenia oprawy z blokiem, a niekoniecznie samego szycia składek.","Tak. Usterka dotyczy połączenia oprawy z blokiem, a niekoniecznie samego szycia składek.","Nie. Usterka dotyczy połączenia oprawy z blokiem, a niekoniecznie samego szycia składek.","Nie. Usterka dotyczy połączenia oprawy z blokiem, a niekoniecznie samego szycia składek."],"task":"Zrób tabelę dla pięciu objawów: miejscowy rozpad grzbietu, odklejona okładka, luźna karta, skręcony blok, fałda wyklejki. Dla każdego określ część, możliwą przyczynę, wymagany dowód i właściwy poziom interwencji."}}'::jsonb),
('introligator-tradycja',7,'8. Kleje, pH i trwałość: dobór bez uszkadzania papieru','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Dobór kleju zależy od celu","text":"Klej powinien pasować do papieru, płótna, tektury i wymaganej elastyczności. PVA bywa używany w oprawach współczesnych, natomiast prace konserwatorskie wymagają szczególnej oceny stabilności, odwracalności i wpływu wilgoci. Sama etykieta ''archiwalny'' nie jest wystarczającym dowodem przydatności do zabytku."},{"heading":"Co oznacza pH materiału","text":"Papier o niekorzystnym składzie i kwasowości może z czasem kruszeć i żółknąć. Stosowanie odpowiedniego papieru konserwatorskiego i stabilnych materiałów pomaga ograniczyć część procesów degradacji, ale nie sprawia, że oprawa jest niezniszczalna. Rozróżniaj własności papieru, kleju i zewnętrznych warunków przechowywania."},{"heading":"Wilgoć w procesie klejenia","text":"Nadmiar wodnego kleju może odkształcić papier i doprowadzić do fałd lub rozwarstwienia. Równomierne nakładanie i dobór właściwej ilości ma znaczenie, ale konkretna technika zależy od materiału. Nie stosuj przypadkowego kleju budowlanego do starych rycin."},{"heading":"Przykład błędnej deklaracji","text":"Właściciel cennej książki kupuje taśmę z napisem ''archival'', chcąc naprawić grzbiet. Samoprzylepny materiał może z czasem powodować przebarwienia i trudności przy usuwaniu. Dla wartościowego obiektu trzeba rozważyć przechowywanie ochronne i konsultację z konserwatorem."},{"heading":"Zadanie porównawcze","text":"Porównaj trzy projekty: nowy zeszyt szkolny, album fotograficzny i historyczny druk. Zapisz funkcję spoiwa, wymagania elastyczności, trwałości, odwracalności, ryzyko wody i odpowiedzialność za dobór. Nie używaj zabytku jako próbki."}],"illustration":"material-introligator-tradycja","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://guides.loc.gov/preserving-your-books/repairing"}],"learning":{"intro":"Klej powinien pasować do papieru, płótna, tektury i wymaganej elastyczności. PVA bywa używany w oprawach współczesnych, natomiast prace konserwatorskie wymagają szczególnej oceny stabilności, odwracalności i wpływu wilgoci. Sama etykieta ''archiwalny'' nie jest wystarczającym dowodem przydatności do zabytku.","situation":"Właściciel cennej książki kupuje taśmę z napisem ''archival'', chcąc naprawić grzbiet. Samoprzylepny materiał może z czasem powodować przebarwienia i trudności przy usuwaniu. Dla wartościowego obiektu trzeba rozważyć przechowywanie ochronne i konsultację z konserwatorem.","question":"Dlaczego określenie ''taśma archiwalna'' nie wystarcza do uzasadnienia naprawy cennej książki?","options":["Bo wszystkie taśmy mają identyczny skład bez względu na producenta.","Bo samoprzylepne taśmy zawsze zwiększają wartość historyczną oprawy.","Bo istotne są rzeczywiste właściwości, usuwalność i wpływ materiału na oryginał.","Bo pH nie ma znaczenia dla papieru i spoiw."],"correct":2,"example":"Bo istotne są rzeczywiste właściwości, usuwalność i wpływ materiału na oryginał.","explanation":"Wartościowe zbiory wymagają kontroli wpływu i odwracalności zabiegów; Library of Congress odradza samoprzylepne taśmy także oznaczane jako archiwalne.","feedback":["Nie. Wartościowe zbiory wymagają kontroli wpływu i odwracalności zabiegów; Library of Congress odradza samoprzylepne taśmy także oznaczane jako archiwalne.","Nie. Wartościowe zbiory wymagają kontroli wpływu i odwracalności zabiegów; Library of Congress odradza samoprzylepne taśmy także oznaczane jako archiwalne.","Tak. Wartościowe zbiory wymagają kontroli wpływu i odwracalności zabiegów; Library of Congress odradza samoprzylepne taśmy także oznaczane jako archiwalne.","Nie. Wartościowe zbiory wymagają kontroli wpływu i odwracalności zabiegów; Library of Congress odradza samoprzylepne taśmy także oznaczane jako archiwalne."],"task":"Porównaj trzy projekty: nowy zeszyt szkolny, album fotograficzny i historyczny druk. Zapisz funkcję spoiwa, wymagania elastyczności, trwałości, odwracalności, ryzyko wody i odpowiedzialność za dobór. Nie używaj zabytku jako próbki."}}'::jsonb),
('introligator-tradycja',8,'9. Konserwacja zabytkowej książki a wykonanie nowej oprawy','{"module":3,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Dwa różne zadania","text":"Nowa oprawa może być projektowana od początku pod wybraną funkcję. Zabytkowa książka zawiera materialne dowody historii: oryginalną skórę, ślady szycia, zapiski właścicieli i dokumentację wcześniejszych napraw. Utrata tych elementów może zmniejszyć jej wartość nawet wtedy, gdy nowa okładka wygląda estetycznie."},{"heading":"Najpierw zabezpieczenie i opis","text":"Przed ingerencją wykonaj zdjęcia, opis stanu, numer identyfikacyjny oraz ocenę, czy zniszczenie postępuje. W wielu przypadkach właściwym działaniem będzie opakowanie ochronne oraz poprawa sposobu przechowywania, a nie natychmiastowa renowacja. Konserwator podejmuje decyzję na podstawie wartości i stanu obiektu."},{"heading":"Przypadek skóry i taśmy","text":"W starych oprawach skóra może kruszeć; stosowanie olejów i przypadkowych preparatów nie jest standardową metodą zabezpieczania. Podobnie taśma klejąca może tworzyć trudne do usunięcia ślady. Najpierw trzeba rozpoznać materiał i możliwe skutki ingerencji."},{"heading":"Przykład z muzeum","text":"Album z 1890 r. ma oderwany fragment grzbietu z oryginalnym złoconym napisem. Propozycja wymiany całej okładziny na nową może usunąć istotne dane historyczne. Muzeum może wybrać stabilizację i opakowanie zamiast przebudowy konstrukcji."},{"heading":"Ćwiczenie etyczne","text":"Przygotuj dwa plany: (A) nowa oprawa notesu, (B) ochrona historycznego albumu. Dla każdego wypisz stan, cel, plan działania, ograniczenia, dokumentację i właściwą kompetencję wykonawcy. W planie B zaznacz czynności, których nie wykonasz bez specjalisty."}],"illustration":"craft-introligator-tradycja","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://guides.loc.gov/preserving-your-books/repairing"}],"learning":{"intro":"Nowa oprawa może być projektowana od początku pod wybraną funkcję. Zabytkowa książka zawiera materialne dowody historii: oryginalną skórę, ślady szycia, zapiski właścicieli i dokumentację wcześniejszych napraw. Utrata tych elementów może zmniejszyć jej wartość nawet wtedy, gdy nowa okładka wygląda estetycznie.","situation":"Album z 1890 r. ma oderwany fragment grzbietu z oryginalnym złoconym napisem. Propozycja wymiany całej okładziny na nową może usunąć istotne dane historyczne. Muzeum może wybrać stabilizację i opakowanie zamiast przebudowy konstrukcji.","question":"Co jest najważniejszym krokiem przed ingerencją w historyczny album z oryginalną okładką?","options":["Dokumentacja stanu i konsultacja konserwatorska dotycząca sensu oraz zakresu zabiegu.","Natychmiastowa wymiana wszystkich starych materiałów na nowe.","Przyklejenie brakujących fragmentów dowolną taśmą.","Zamalowanie starych oznaczeń, aby uzyskać jednolitą barwę."],"correct":0,"example":"Dokumentacja stanu i konsultacja konserwatorska dotycząca sensu oraz zakresu zabiegu.","explanation":"Przed konserwacją trzeba ocenić wartość materialnych śladów i dokumentować stan, a nie automatycznie wymieniać historyczne elementy.","feedback":["Tak. Przed konserwacją trzeba ocenić wartość materialnych śladów i dokumentować stan, a nie automatycznie wymieniać historyczne elementy.","Nie. Przed konserwacją trzeba ocenić wartość materialnych śladów i dokumentować stan, a nie automatycznie wymieniać historyczne elementy.","Nie. Przed konserwacją trzeba ocenić wartość materialnych śladów i dokumentować stan, a nie automatycznie wymieniać historyczne elementy.","Nie. Przed konserwacją trzeba ocenić wartość materialnych śladów i dokumentować stan, a nie automatycznie wymieniać historyczne elementy."],"task":"Przygotuj dwa plany: (A) nowa oprawa notesu, (B) ochrona historycznego albumu. Dla każdego wypisz stan, cel, plan działania, ograniczenia, dokumentację i właściwą kompetencję wykonawcy. W planie B zaznacz czynności, których nie wykonasz bez specjalisty."}}'::jsonb),
('introligator-tradycja',9,'10. Przechowywanie książek: wilgotność, światło i opakowania','{"module":3,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Najtańsza konserwacja bywa zapobiegawcza","text":"Wiele uszkodzeń ogranicza się przez stabilne warunki przechowywania, właściwe podparcie i poprawne obchodzenie się z książką. Wilgoć sprzyja rozwojowi pleśni oraz odkształceniom, a nadmiernie suche lub niestabilne warunki mogą zwiększać kruchość niektórych materiałów. Bez danych o zbiorze nie stosuj jednej recepty dla wszystkich obiektów."},{"heading":"Światło, kurz i zbyt ciasna półka","text":"Długotrwała ekspozycja na światło przyspiesza blaknięcie wielu barwników. Zbyt ciasne ustawienie utrudnia wyjmowanie książki i może uszkadzać grzbiet; duże albumy mogą wymagać przechowywania poziomego. Odpowiednie pudełka i obwoluty pomagają chronić rzadko używane zbiory."},{"heading":"Prawidłowe chwytanie książki","text":"Wyciąganie książki za górną krawędź grzbietu sprzyja jej uszkodzeniom. Należy zapewnić dostęp i podparcie, a przed otwarciem kruchego obiektu ocenić, czy nie trzeba użyć podpórki. Ręce powinny być czyste; rękawiczki nie są automatycznie bezpieczniejsze w każdej sytuacji."},{"heading":"Przykład niewłaściwego magazynowania","text":"Duże księgi ustawiono pionowo, bardzo ściśnięte między innymi tomami. Przy częstym wyciąganiu jedna ma oderwaną górną część grzbietu. Zmiana sposobu przechowywania może ograniczyć kolejne uszkodzenia bez wykonywania niepotrzebnych napraw."},{"heading":"Ćwiczenie organizacyjne","text":"Zaprojektuj regał dla 20 tomów: 12 standardowych, 5 dużych i 3 rzadko używane. Określ sposób podparcia, układ, ochronę przed kurzem, kontrolę zmian warunków i zasady wyjmowania. Dodaj rejestr dwóch zauważonych uszkodzeń."}],"illustration":"introligator-anatomia","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://loc.gov/preservation/about/faqs/books.html"}],"learning":{"intro":"Wiele uszkodzeń ogranicza się przez stabilne warunki przechowywania, właściwe podparcie i poprawne obchodzenie się z książką. Wilgoć sprzyja rozwojowi pleśni oraz odkształceniom, a nadmiernie suche lub niestabilne warunki mogą zwiększać kruchość niektórych materiałów. Bez danych o zbiorze nie stosuj jednej recepty dla wszystkich obiektów.","situation":"Duże księgi ustawiono pionowo, bardzo ściśnięte między innymi tomami. Przy częstym wyciąganiu jedna ma oderwaną górną część grzbietu. Zmiana sposobu przechowywania może ograniczyć kolejne uszkodzenia bez wykonywania niepotrzebnych napraw.","question":"Co jest rozsądnym pierwszym działaniem dla rzadko używanego, kruchego albumu o wartości historycznej?","options":["Intensywne czyszczenie silnym preparatem i wymiana grzbietu.","Przechowywanie na mokrej półce, aby papier nie wysychał.","Codzienne zaginanie wszystkich kart w celu poprawy elastyczności.","Odpowiednie opakowanie ochronne i stabilne warunki po fachowej ocenie."],"correct":3,"example":"Odpowiednie opakowanie ochronne i stabilne warunki po fachowej ocenie.","explanation":"Działania prewencyjne mogą zmniejszyć dalsze uszkodzenia bez ingerowania w oryginalny materiał.","feedback":["Nie. Działania prewencyjne mogą zmniejszyć dalsze uszkodzenia bez ingerowania w oryginalny materiał.","Nie. Działania prewencyjne mogą zmniejszyć dalsze uszkodzenia bez ingerowania w oryginalny materiał.","Nie. Działania prewencyjne mogą zmniejszyć dalsze uszkodzenia bez ingerowania w oryginalny materiał.","Tak. Działania prewencyjne mogą zmniejszyć dalsze uszkodzenia bez ingerowania w oryginalny materiał."],"task":"Zaprojektuj regał dla 20 tomów: 12 standardowych, 5 dużych i 3 rzadko używane. Określ sposób podparcia, układ, ochronę przed kurzem, kontrolę zmian warunków i zasady wyjmowania. Dodaj rejestr dwóch zauważonych uszkodzeń."}}'::jsonb),
('introligator-tradycja',10,'11. Kosztorys i plan prac oprawy: materiał, odpady i czas','{"module":3,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Koszt ma więcej niż jedną składową","text":"Wycena oprawy uwzględnia papier, tekturę, płótno, nici, klej, materiały próbne, odpady, robociznę i koszty pośrednie. Przy starych książkach wycena konserwatorska jest dodatkowo związana z dokumentacją i ryzykiem, a nie wyłącznie liczbą stron."},{"heading":"Przykład rachunku na notesie","text":"Do 10 notesów zaplanowano 40 arkuszy na każdy egzemplarz, czyli 400 arkuszy. Przy kosztach 0,20 zł/arkusz papier kosztuje 80 zł. Do tego przyjmij tekturę i okleinę łącznie 60 zł, inne materiały 20 zł oraz 4 h pracy po 50 zł = 200 zł. Koszty bezpośrednie w przykładzie to 360 zł."},{"heading":"Nie myl marży z zyskiem netto","text":"Jeśli 10 notesów sprzedano po 50 zł, przychód to 500 zł, a po odjęciu 360 zł zostaje 140 zł przed innymi kosztami i podatkami. To nie jest jeszcze dowód faktycznej rentowności bez uwzględnienia strat, wysyłek i obsługi klienta."},{"heading":"Harmonogram zależności","text":"Nie można zacząć końcowego łączenia oprawy, zanim blok nie zostanie odpowiednio przygotowany i przyjęty do montażu. W harmonogramie wydziel osobno przygotowanie składek, szycie, grzbiet, okładkę, schnięcie odpowiednich połączeń i odbiór."},{"heading":"Ćwiczenie w tabeli","text":"Opracuj budżet 20 notesów o tym samym formacie. Przy stałej cenie papieru dodaj 5% planistycznych strat i oddziel koszty stałe od zmiennych. Zapisz cenę, roboczogodziny oraz warunki nieprzewidzianej poprawki i terminu dostawy."}],"illustration":"mastery-introligator-tradycja","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://bindery.berkeley.edu/campus-libraries/definitions-common-terms"}],"learning":{"intro":"Wycena oprawy uwzględnia papier, tekturę, płótno, nici, klej, materiały próbne, odpady, robociznę i koszty pośrednie. Przy starych książkach wycena konserwatorska jest dodatkowo związana z dokumentacją i ryzykiem, a nie wyłącznie liczbą stron.","situation":"Nie można zacząć końcowego łączenia oprawy, zanim blok nie zostanie odpowiednio przygotowany i przyjęty do montażu. W harmonogramie wydziel osobno przygotowanie składek, szycie, grzbiet, okładkę, schnięcie odpowiednich połączeń i odbiór.","question":"W przykładzie 10 notesów kosztuje bezpośrednio 360 zł, a sprzedano je po 50 zł za sztukę. Ile zostaje przed innymi kosztami i podatkami?","options":["360 zł.","140 zł.","500 zł.","860 zł."],"correct":1,"example":"140 zł.","explanation":"10×50=500 zł przychodu, 500−360=140 zł pozostałej kwoty, która nie musi być zyskiem netto.","feedback":["Nie. 10×50=500 zł przychodu, 500−360=140 zł pozostałej kwoty, która nie musi być zyskiem netto.","Tak. 10×50=500 zł przychodu, 500−360=140 zł pozostałej kwoty, która nie musi być zyskiem netto.","Nie. 10×50=500 zł przychodu, 500−360=140 zł pozostałej kwoty, która nie musi być zyskiem netto.","Nie. 10×50=500 zł przychodu, 500−360=140 zł pozostałej kwoty, która nie musi być zyskiem netto."],"task":"Opracuj budżet 20 notesów o tym samym formacie. Przy stałej cenie papieru dodaj 5% planistycznych strat i oddziel koszty stałe od zmiennych. Zapisz cenę, roboczogodziny oraz warunki nieprzewidzianej poprawki i terminu dostawy."}}'::jsonb),
('introligator-tradycja',11,'12. Praca końcowa: zaprojektuj i skontroluj notes szyty','{"module":3,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Specyfikacja zamiast zgadywania","text":"Przygotuj projekt notesu z 64 stronami w czterech składkach po 16 stron. Każda składka to cztery arkusze złożone raz. Docelowy format jest umowny, np. A5; sprawdź sposób składania arkuszy, margines przy grzbiecie, rozstaw punktów szycia i dobór okładki."},{"heading":"Ile części potrzebujesz","text":"64 strony / 4 strony na arkusz = 16 arkuszy. Przy czterech arkuszach w składce masz cztery składki. Dodaj odpowiednie wyklejki, materiał okładkowy, tekturę i nić. Nie mieszaj liczenia pojedynczych kart (32) z liczbą arkuszy przed złożeniem (16)."},{"heading":"Mapa procesu","text":"Najpierw makieta i impozycja stron, potem składanie, sprawdzenie kierunku włókien, wyznaczenie punktów szycia, połączenie bloku, konstrukcja okładki, połączenie z wyklejkami i kontrola otwierania. Przy każdym etapie zapisz jeden warunek poprawności i dokument kontrolny."},{"heading":"Scenariusz odbiorowy","text":"Po wykonaniu notesu jedna okładka otwiera się tylko do niewielkiego kąta, a przegub mocno napina wyklejkę. Nie należy uznać całości za gotową tylko dlatego, że 64 strony są we właściwej kolejności. Potrzebna jest ocena strefy przegubu."},{"heading":"Praca do oddania","text":"Narysuj trzy widoki notesu, arkusz impozycji 16 stron, tabelę wszystkich materiałów, rozstaw punktów szycia i protokół jakości zawierający co najmniej 10 kryteriów. Dodaj analizę przyczyny źle pracującej okładki oraz propozycję kontroli zapobiegawczej."}],"illustration":"introligator-skladka","references":[{"label":"Źródło do dalszego sprawdzenia","url":"https://guides.library.utoronto.ca/c.php?g=747378&p=5418809"}],"learning":{"intro":"Przygotuj projekt notesu z 64 stronami w czterech składkach po 16 stron. Każda składka to cztery arkusze złożone raz. Docelowy format jest umowny, np. A5; sprawdź sposób składania arkuszy, margines przy grzbiecie, rozstaw punktów szycia i dobór okładki.","situation":"Po wykonaniu notesu jedna okładka otwiera się tylko do niewielkiego kąta, a przegub mocno napina wyklejkę. Nie należy uznać całości za gotową tylko dlatego, że 64 strony są we właściwej kolejności. Potrzebna jest ocena strefy przegubu.","question":"W projekcie 64-stronicowego notesu złożonego z arkuszy po cztery strony — ile potrzeba arkuszy przed złożeniem?","options":["64.","32.","16.","4."],"correct":2,"example":"16.","explanation":"Jeden arkusz po złożeniu daje cztery strony, więc 64/4=16 arkuszy, czyli 32 karty.","feedback":["Nie. Jeden arkusz po złożeniu daje cztery strony, więc 64/4=16 arkuszy, czyli 32 karty.","Nie. Jeden arkusz po złożeniu daje cztery strony, więc 64/4=16 arkuszy, czyli 32 karty.","Tak. Jeden arkusz po złożeniu daje cztery strony, więc 64/4=16 arkuszy, czyli 32 karty.","Nie. Jeden arkusz po złożeniu daje cztery strony, więc 64/4=16 arkuszy, czyli 32 karty."],"task":"Narysuj trzy widoki notesu, arkusz impozycji 16 stron, tabelę wszystkich materiałów, rozstaw punktów szycia i protokół jakości zawierający co najmniej 10 kryteriów. Dodaj analizę przyczyny źle pracującej okładki oraz propozycję kontroli zapobiegawczej."}}'::jsonb)
on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='12 szczegółowych lekcji introligatorstwa: budowa książki, kierunek włókien papieru i tektury, narzędzia, folio i składki, szycie, oprawa twarda, diagnostyka grzbietu, kleje i materiały, konserwacja historycznych książek, przechowywanie, kosztorys i własny projekt notesu. Kurs poznawczy i praktyczny do ćwiczeń na nowych materiałach, nie nadaje formalnych uprawnień konserwatorskich.' where slug='introligator-tradycja';
update public.ta_course_previews set
curiosity='Dlaczego kierunek włókien papieru decyduje o tym, czy książka będzie się wygodnie otwierała?',
scenario='Tworzysz 64-stronicowy notes z czterech składek. Liczysz arkusze, dobierasz materiał i projektujesz przegub twardej okładki.',
outcome_1='Rozpoznasz 10 części książki, materiały i narzędzia oraz różnicę między kartą, stroną, folio i składką.',
outcome_2='Policzysz liczbę arkuszy, przygotujesz szablon szycia i zaprojektujesz poprawnie działającą twardą oprawę.',
outcome_3='Odróżnisz naprawę nowej oprawy od konserwacji zabytku i sporządzisz protokół jakości.',
source_url='https://guides.library.utoronto.ca/c.php?g=747378&p=5418809',
module_titles='["1. Anatomia i materiałoznawstwo książki (1–4)","2. Szycie, oprawa twarda, diagnostyka i kleje (5–8)","3. Konserwacja, magazynowanie, kosztorys i projekt (9–12)"]'::jsonb,
review_status='review_needed',
editorial_note='12 lekcji z przykładami, obliczeniami, ćwiczeniami i źródłami bibliotecznymi. Przed deklarowaniem pełnej nauki zawodu wymagana recenzja praktyka introligatorstwa, test interfejsu i ocena zadań. Prace nad zabytkami wymagają specjalisty.'
where course_slug='introligator-tradycja';
COMMIT;
